leadActions:
REQUIRED (the only failing test in apps/api): apps/api/tests/provider-moderation.test.ts lines 484-505, the test 'a flag without a PencilLift category on child input only logs a code; the answer is graded'. Its assertion IS the CS-R2-03 defect (a provider flag the mapping did not know was graded, coached and never reached the parent), so it has to be replaced, not weakened. I do not own that file. Verified post-fix behaviour for exactly that fixture with a scratchpad probe (/tmp/claude-0/-home-user-claudecampsophie/b1b9c04d-3d1c-58be-b925-a948687d722a/scratchpad/hardening/safety-flags-r2-fix/probe-pm484.test.ts): stages = ['homework_extraction'] only, child_feedback kinds = ['safety'], one report {screen_categories: ['abuse','violence'], status: 'escalated', family_visible: true}, assignment 'ready', log moderation_flag_child_input/PROVIDER_HARASSMENT still present, one safety_flag_email job. Exact replacement:

  // CS-R2-03: this test used to assert 'only logs a code; the answer is graded'. That assertion was
  // the defect: a provider flag whose category maps to nothing reached no one. The child-input
  // screen now fails closed (moderation.ts providerSafetyScreen, PROVIDER_FALLBACK_CATEGORY).
  it('a flag with no mapped PencilLift category is answered and reported (CS-R2-03)', async () => {
    const answer = 'The fox ran home fast [mock-moderation:harassment]';
    const question: ScriptedQuestion = {
      ...PROVIDER_ONLY,
      number: '5',
      prompt: 'What did the fox do?',
      answer,
      subject: 'reading',
    };
    const scan = await queuedScan();
    const ai = scriptedModel([question]);
    await runJobs(deps, handlers(ai, createMockModerationClient()));
    expect(stageRequests(ai, 'private_grading')).toEqual([]);
    expect((await feedback(scan, question.prompt)).map((f) => f.kind)).toEqual(['safety']);
    expect(await reports(scan)).toMatchObject([
      { screen_categories: ['abuse', 'violence'], status: 'escalated', family_visible: true },
    ]);
    expect(api.logs).toContainEqual({
      level: 'warn',
      event: 'moderation_flag_child_input',
      code: 'PROVIDER_HARASSMENT',
    });
    expectNoChildTextInLogs(answer);
  });
